style.css:
@-moz-document domain("chat.openai.com") {
/* Global background and font */
  body {
    background: linear-gradient(to bottom right, #ffdee9, #7f0909, #ffd6e8) !important;
    font-family: 'Pacifico', cursive !important;
    color: #fff0f5 !important;
  }

  /* Chat container */
  .flex.h-full.w-full.flex-col {
    background-color: rgba(51, 0, 0, 0.8) !important;
    border-radius: 16px;
    backdrop-filter: blur(12px);
    padding: 12px;
    border: 2px solid #ffc0cb;
  }

  /* Side menu background */
  .flex.h-full.flex-col.flex-1.bg-token-main-surface {
    background: linear-gradient(to bottom, #300000, #ffdde0) !important;
    border-right: 3px solid #ffb6c1;
  }

  /* Chat bubbles */
  .group.w-full.text-token-text-primary {
    background-color: rgba(255, 182, 193, 0.08) !important;
    border-left: 3px solid #ffb6c1;
    padding-left: 12px;
  }

  /* Buttons */
  .btn, .btn-primary, .text-token-text-button, .btn.relative {
    background-color: #ffb6c1 !important;
    color: #4a0100 !important;
    border-radius: 12px !important;
    font-weight: bold !important;
    font-family: 'Pacifico', cursive !important;
    box-shadow: 0 4px 12px rgba(255, 182, 193, 0.4) !important;
  }

  .btn:hover {
    background-color: #ffd6e8 !important;
    box-shadow: 0 0 10px #ffc0cb;
    transform: scale(1.03);
    transition: 0.3s ease;
  }

  /* Headers / Titles */
  .text-lg.font-semibold, h1, h2, h3 {
    color: #ffc0cb !important;
    font-family: 'Pacifico', cursive !important;
    text-shadow: 1px 1px 3px #000;
  }

  /* Links */
  a {
    color: #ffd700 !important;
    font-weight: bold;
    text-decoration: none;
  }

  a:hover {
    text-decoration: underline;
    text-shadow: 0 0 6px #ffd700;
  }

  /* Input Box */
  textarea {
    background-color: #2e0d00 !important;
    color: #fffbe7 !important;
    border-radius: 10px !important;
    border: 2px solid #ffb6c1 !important;
    box-shadow: 0 0 10px #ff69b4 !important;
    font-family: 'Pacifico', cursive !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background: #ffc0cb;
    border-radius: 8px;
  }
}
